];

const crm = $node["Parser Updater Output"].json.crm_mirror || {};

const ESTADO_MAP = {
  "Consulta nueva": "CONSULTA_NUEVA",
  "Coordinar disponibilidad": "COORDINAR_DISPONIBILIDAD",
  "Agendado": "AGENDADO",
  "Revisión completa": "REVISION_COMPLETA",
  "Atención humana": "ATENCION_HUMANA",

  CONSULTA_NUEVA: "CONSULTA_NUEVA",
  COORDINAR_DISPONIBILIDAD: "COORDINAR_DISPONIBILIDAD",
  AGENDADO: "AGENDADO",
  REVISION_COMPLETA: "REVISION_COMPLETA",
  ATENCION_HUMANA: "ATENCION_HUMANA",
};

const FLAG_MAP = {
  "Presupuestando": "PRESUPUESTANDO",
  "Presupuesto enviado": "PRESUPUESTO_ENVIADO",
  "Aceptado": "ACEPTADO",
  "Re-compra": "RECOMPRA",
  "Perdido": "PERDIDO",

  PRESUPUESTANDO: "PRESUPUESTANDO",
  PRESUPUESTO_ENVIADO: "PRESUPUESTO_ENVIADO",
  ACEPTADO: "ACEPTADO",
  RECOMPRA: "RECOMPRA",
  PERDIDO: "PERDIDO",
};

const mappedEstado = crm.estado ? ESTADO_MAP[crm.estado] ?? null : null;
const mappedFlag = crm.flag ? FLAG_MAP[crm.flag] ?? null : null;

const patch = {
  estado: mappedEstado,
  flag: mappedFlag,
  necesita_humano: crm.necesita_humano,
};

// only include motivo_perdida when flag is PERDIDO
if (mappedFlag === "PERDIDO" && crm.motivo_perdida) {
  patch.motivo_perdida = crm.motivo_perdida;
}

const clean = Object.fromEntries(
  Object.entries(patch).filter(([, v]) => v !== null && v !== undefined)
);

return [{ json: clean }];

const revisionPatch = $node["Parser Updater Output"].json.lead_revision_patch || {};
const effectiveRevisionId = ($json.effective_revision_id && $json.effective_revision_id !== 0) ? $json.effective_revision_id : null;

const cleanPatch = Object.fromEntries(
  Object.entries(revisionPatch).filter(([, v]) => v !== null && v !== undefined && v !== "")
);

// Inject approval PENDING when a scheduled date is being set
if (cleanPatch.scheduled_date) {
  cleanPatch.appointment_approval_status = "PENDING";
  cleanPatch.appointment_approval_sent_at = new Date().toISOString();
}

return [
  {
    json: {
      effective_revision_id: effectiveRevisionId,
      revision_patch: cleanPatch
    }
  }
];

const updater = $node["Parser Updater Output"].json;
const bookingSignals = updater.booking_signals || {};
const revPatch = updater.lead_revision_patch || {};

const dayText = (bookingSignals.preferred_day_text || "").toLowerCase().trim();
const today = new Date();
let targetDate = new Date(today);

if (dayText.match(/^\d{4}-\d{2}-\d{2}/)) {
  const parsed = new Date(dayText.match(/\d{4}-\d{2}-\d{2}/)[0] + "T12:00:00");
  if (parsed > today) {
    targetDate = parsed;
  } else {
    targetDate = new Date(parsed);
    targetDate.setDate(parsed.getDate() + 7);
  }
} else if (dayText.includes("mañana")) {
  targetDate.setDate(today.getDate() + 1);
} else if (dayText.includes("pasado")) {
  targetDate.setDate(today.getDate() + 2);
} else {
  const dayMap = {
    "lunes": 1, "martes": 2, "miércoles": 3, "miercoles": 3,
    "jueves": 4, "viernes": 5, "sábado": 6, "sabado": 6, "domingo": 0
  };
  const targetDay = dayMap[dayText];
  if (targetDay !== undefined) {
    const todayDay = today.getDay();
    let daysAhead = targetDay - todayDay;
    if (daysAhead <= 0) daysAhead += 7;
    targetDate.setDate(today.getDate() + daysAhead);
  }
}

const preferred_day = targetDate.toISOString().split("T")[0];

const timeRaw = (bookingSignals.preferred_time_text || revPatch.turno_hora || "10:00").toString().trim();
let preferred_time = "10:00";
const match = timeRaw.match(/^(\d{1,2})[\s:hH]?(\d{0,2})/);
if (match) {
  const hours = match[1].padStart(2, "0");
  const minutes = (match[2] && match[2].length === 2) ? match[2] : "00";
  preferred_time = `${hours}:${minutes}`;
}

const direccion = revPatch.direccion_texto || "";
const zoneDetail = revPatch.zone_detail || "";
const zoneGroup = revPatch.zone_group || "";
const address = [direccion, zoneDetail, zoneGroup].filter(Boolean).join(", ");

return [{
  json: {
    address: address || "Sin direccion",
    preferred_day,
    preferred_time,
    zone_group: zoneGroup,
    zone_detail: zoneDetail,
    lead_revision_patch: revPatch,
    booking_signals: bookingSignals
  }
}];

const ZONA_CERO = {
  MELO: "Melo y Panamericana, Nordelta, Buenos Aires, Argentina",
  SANTA_CATALINA: "Santa Catalina Puerta 2, Benavidez, Buenos Aires, Argentina"
};

function isAlternatingWeek(dateStr) {
  const anchor = new Date("2026-04-06T00:00:00");
  const target = new Date(dateStr + "T00:00:00");
  const deltaDays = Math.floor((target - anchor) / (1000 * 60 * 60 * 24));
  if (deltaDays < 0) return false;
  return (Math.floor(deltaDays / 7) % 2) === 0;
}

function getZonaCero(dateStr) {
  const date = new Date(dateStr + "T00:00:00");
  const dow = date.getDay();
  const alternating = isAlternatingWeek(dateStr);
  if (dow === 1) return alternating ? ZONA_CERO.MELO : ZONA_CERO.SANTA_CATALINA;
  if (dow === 2) return ZONA_CERO.SANTA_CATALINA;
  if (dow === 3) return ZONA_CERO.SANTA_CATALINA;
  if (dow === 4) return ZONA_CERO.MELO;
  if (dow === 5) return ZONA_CERO.MELO;
  if (dow === 6) return ZONA_CERO.SANTA_CATALINA;
  return ZONA_CERO.MELO;
}

const dateParserOutput = $node["Date Parser"].json;
const preferred_day = dateParserOutput["preferred_day"];
const preferred_time = dateParserOutput["preferred_time"];
const address = dateParserOutput["address"];
const zone_group = dateParserOutput["zone_group"];
const zone_detail = dateParserOutput["zone_detail"];
const lead_revision_patch = dateParserOutput["lead_revision_patch"];
const booking_signals = dateParserOutput["booking_signals"];

// Get appointments from previous node
const appointments = $input.all().map(i => i.json).filter(i => i.time);

let origin = getZonaCero(preferred_day);

if (appointments && appointments.length > 0) {
  const sorted = appointments.sort((a, b) => a.time.localeCompare(b.time));
  const proposedMinutes = parseInt(preferred_time.split(":")[0]) * 60 + parseInt(preferred_time.split(":")[1]);

  let lastBefore = null;
  for (const apt of sorted) {
    const aptMinutes = parseInt(apt.time.split(":")[0]) * 60 + parseInt(apt.time.split(":")[1]);
    if (aptMinutes < proposedMinutes) lastBefore = apt;
  }

  if (lastBefore && lastBefore.address) origin = lastBefore.address;
}

return [{
  json: {
    address,
    preferred_day,
    preferred_time,
    zone_group,
    zone_detail,
    origin_used: origin,
    lead_revision_patch,
    booking_signals
  }
}];

const mapsResult = $json;
const dateParserOutput = $node["Date Parser"].json;
const calcOutput = $node["Calculate Distance"].json;

const element = mapsResult.rows?.[0]?.elements?.[0];
let distanceKm = 5; // fallback
if (element?.status === "OK") {
  distanceKm = Math.round((element.distance.value / 1000) * 10) / 10;
}

return [{
  json: {
    address: calcOutput.address,
    preferred_day: calcOutput.preferred_day,
    preferred_time: calcOutput.preferred_time,
    zone_group: calcOutput.zone_group,
    zone_detail: calcOutput.zone_detail,
    distance_km: distanceKm,
    origin_used: calcOutput.origin_used,
    lead_revision_patch: calcOutput.lead_revision_patch,
    booking_signals: calcOutput.booking_signals
  }
}];

